function CampaignEquipmentPanel({ campaign, onRefresh }) {
  const { user } = useAuth();
  const [items, setItems] = useState([]);
  const [form, setForm] = useState(null);
  const [error, setError] = useState(null);

  const loadItems = useCallback(() => {
    if (!campaign?.id) return;
    equipmentAPI
      .list({ campaign: campaign.id })
      .then((list) => setItems(Array.isArray(list) ? list : []))
      .catch(() => setItems([]));
  }, [campaign?.id]);

  useEffect(() => {
    loadItems();
  }, [loadItems]);

  const campaignItems = items.filter((i) => i.scope === "CAMPAIGN");
  const templates = items.filter((i) => i.scope === "TEMPLATE");
  const siteItems = items.filter((i) => i.scope === "SITE");

  const canDeleteCatalogItem = (item) => {
    if (!user) return false;
    if (user.is_staff) return true;
    if (item.scope === "TEMPLATE") return false;
    if (item.created_by != null && Number(item.created_by) === Number(user.id)) {
      return true;
    }
    if (
      item.scope === "CAMPAIGN" &&
      campaign?.gm?.id != null &&
      Number(campaign.gm.id) === Number(user.id)
    ) {
      return true;
    }
    return false;
  };

  const startCreate = () => {
    setForm({
      name: "",
      description: "",
      category: "other",
      load_slots: 1,
      quality: 1,
      coin_value: "",
      available_when_adding: true,
    });
    setError(null);
  };

  const handleSave = async () => {
    if (!form?.name?.trim()) {
      setError("Name required.");
      return;
    }
    setError(null);
    try {
      await equipmentAPI.create({
        name: form.name.trim(),
        description: form.description || "",
        category: form.category,
        load_slots: Number(form.load_slots) || 1,
        quality: Number(form.quality) || 1,
        coin_value: form.coin_value === "" ? null : Number(form.coin_value),
        scope: "CAMPAIGN",
        campaign: campaign.id,
        available_when_adding: Boolean(form.available_when_adding),
      });
      setForm(null);
      loadItems();
      onRefresh?.();
    } catch (e) {
      setError(e.message || "Could not save equipment.");
    }
  };

  const toggleAccess = async (item, enabled) => {
    try {
      await equipmentAPI.setCampaignAccess(item.id, campaign.id, enabled);
      loadItems();
    } catch (e) {
      setError(e.message || "Could not update access.");
    }
  };

  const handleDelete = async (item) => {
    if (!window.confirm(`Delete catalog item “${item.name}”?`)) return;
    setError(null);
    try {
      await equipmentAPI.delete(item.id);
      loadItems();
      onRefresh?.();
    } catch (e) {
      setError(e.message || "Could not delete equipment.");
    }
  };

  return (
    <div style={S.card}>
      <span style={S.sectionLbl}>Equipment catalog</span>
      {error ? (
        <div style={{ color: "var(--sheet-label)", fontSize: "11px", marginBottom: "8px" }}>
          {error}
        </div>
      ) : null}
      <div style={{ color: "var(--text-muted)", fontSize: "11px", marginBottom: "6px" }}>
        Campaign library (this table only — not site catalog)
      </div>
      {campaignItems.length === 0 && !form ? (
        <div style={{ color: "var(--text-dim)", fontSize: "12px", marginBottom: "8px" }}>
          No custom equipment yet.
        </div>
      ) : (
        campaignItems.map((item) => (
          <div
            key={item.id}
            style={{
              padding: "6px 0",
              borderBottom: "1px solid var(--bg-header)",
              fontSize: "12px",
            }}
          >
            <strong style={{ color: "var(--text-primary)" }}>{item.name}</strong>
            <span style={{ color: "var(--text-dim)", marginLeft: "8px" }}>
              {categoryLabel(item.category)} · load {item.load_slots} · Q
              {item.quality}
            </span>
            <label style={{ marginLeft: "12px", color: "var(--text-muted)", fontSize: "11px" }}>
              <input
                type="checkbox"
                checked={item.available_when_adding}
                onChange={(e) =>
                  equipmentAPI
                    .update(item.id, {
                      available_when_adding: e.target.checked,
                    })
                    .then(() => loadItems())
                }
              />
              Available when adding
            </label>
            {canDeleteCatalogItem(item) ? (
              <button
                type="button"
                style={{
                  ...S.btn,
                  marginLeft: "12px",
                  fontSize: "11px",
                  color: "var(--sheet-label)",
                }}
                onClick={() => handleDelete(item)}
              >
                Delete
              </button>
            ) : null}
          </div>
        ))
      )}
      {templates.length > 0 ? (
        <div style={{ marginTop: "10px" }}>
          <div style={{ color: "var(--text-muted)", fontSize: "11px", marginBottom: "6px" }}>
            SRD templates (on for this campaign unless you disable)
          </div>
          {templates.map((item) => (
            <div
              key={`access-${item.id}`}
              style={{
                display: "flex",
                alignItems: "center",
                gap: "8px",
                fontSize: "11px",
                color: "var(--hftf-text-cream)",
                marginBottom: "4px",
                flexWrap: "wrap",
              }}
            >
              <label style={{ display: "inline-flex", alignItems: "center" }}>
                <input
                  type="checkbox"
                  checked={Boolean(item.enabled_for_campaign)}
                  onChange={(e) => toggleAccess(item, e.target.checked)}
                  style={{ marginRight: "6px" }}
                />
                Template: {item.name}
              </label>
              {canDeleteCatalogItem(item) ? (
                <button
                  type="button"
                  style={{
                    ...S.btn,
                    fontSize: "10px",
                    color: "var(--sheet-label)",
                    padding: "2px 6px",
                  }}
                  onClick={() => handleDelete(item)}
                >
                  Delete
                </button>
              ) : null}
            </div>
          ))}
        </div>
      ) : null}
      {siteItems.length > 0 ? (
        <div style={{ marginTop: "10px" }}>
          <div style={{ color: "var(--text-muted)", fontSize: "11px", marginBottom: "6px" }}>
            Site catalog (hidden from add-item until you enable for this campaign)
          </div>
          {siteItems.map((item) => (
            <div
              key={`access-${item.id}`}
              style={{
                display: "flex",
                alignItems: "center",
                gap: "8px",
                fontSize: "11px",
                color: "var(--hftf-text-cream)",
                marginBottom: "4px",
                flexWrap: "wrap",
              }}
            >
              <label style={{ display: "inline-flex", alignItems: "center" }}>
                <input
                  type="checkbox"
                  checked={Boolean(item.enabled_for_campaign)}
                  onChange={(e) => toggleAccess(item, e.target.checked)}
                  style={{ marginRight: "6px" }}
                />
                Site: {item.name}
              </label>
              {canDeleteCatalogItem(item) ? (
                <button
                  type="button"
                  style={{
                    ...S.btn,
                    fontSize: "10px",
                    color: "var(--sheet-label)",
                    padding: "2px 6px",
                  }}
                  onClick={() => handleDelete(item)}
                >
                  Delete
                </button>
              ) : null}
            </div>
          ))}
        </div>
      ) : null}
      {form ? (
        <div style={{ marginTop: "10px" }}>
          <input
            style={S.inp}
            placeholder="Name"
            value={form.name}
            onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))}
          />
          <textarea
            style={{ ...S.inp, minHeight: "48px", marginTop: "6px" }}
            placeholder="Description"
            value={form.description}
            onChange={(e) =>
              setForm((p) => ({ ...p, description: e.target.value }))
            }
          />
          <div style={{ display: "flex", gap: "8px", marginTop: "6px", flexWrap: "wrap" }}>
            <div>
              <span style={{ fontSize: "11px", color: "var(--text-muted)" }}>Category</span>
              <select
                style={S.select}
                value={form.category}
                onChange={(e) =>
                  setForm((p) => ({ ...p, category: e.target.value }))
                }
              >
                {EQUIPMENT_CATEGORY_OPTIONS.map((o) => (
                  <option key={o.value} value={o.value}>{o.label}</option>
                ))}
              </select>
            </div>
            <div>
              <span style={{ fontSize: "11px", color: "var(--text-muted)" }}>Load slots</span>
              <input
                style={{ ...S.inp, width: "60px" }}
                type="number"
                min="0"
                max="2"
                aria-label="Load slots"
                value={form.load_slots}
                onChange={(e) =>
                  setForm((p) => ({ ...p, load_slots: e.target.value }))
                }
              />
            </div>
            <div>
              <span style={{ fontSize: "11px", color: "var(--text-muted)" }}>Quality (Q0–Q3)</span>
              <input
                style={{ ...S.inp, width: "60px" }}
                type="number"
                min="0"
                max="3"
                aria-label="Quality"
                value={form.quality}
                onChange={(e) =>
                  setForm((p) => ({ ...p, quality: e.target.value }))
                }
              />
            </div>
          </div>
          <div style={S.row}>
            <button onClick={handleSave} style={S.btnPrimary}>Save</button>
            <button onClick={() => setForm(null)} style={S.btnGhost}>
              Cancel
            </button>
          </div>
        </div>
      ) : (
        <button onClick={startCreate} style={{ ...S.btnPrimary, marginTop: "8px" }}>
          + New equipment
        </button>
      )}
    </div>
  );
}

