/**
 * The faction fields the NPC sheet edits, in the shape it PATCHes. Used for
 * both the loaded state and the save baseline, so the two compare cleanly.
 */
export function npcFactionValuesFromApi(f) {
  return {
    name: f.name || "",
    faction_type: f.faction_type || "",
    level: typeof f.level === "number" ? f.level : 0,
    hold: f.hold || "weak",
    reputation: typeof f.reputation === "number" ? f.reputation : 0,
    contacts: Array.isArray(f.contacts) ? f.contacts : [],
    inventory: normalizeCharacterInventory(
      Array.isArray(f.inventory) ? f.inventory : [],
    ),
    faction_status: normalizeFactionStatusMap(
      f.faction_status && typeof f.faction_status === "object"
        ? f.faction_status
        : {},
    ),
    crew_notes: f.crew_notes || "",
    visible_to_players: !!f.visible_to_players,
    players_see_tier: f.players_see_tier !== false,
    players_see_hold: f.players_see_hold !== false,
    players_see_reputation: f.players_see_reputation !== false,
    players_see_notes: f.players_see_notes !== false,
    players_see_npcs: f.players_see_npcs !== false,
    players_see_identity: f.players_see_identity !== false,
    players_see_inventory: f.players_see_inventory !== false,
    players_see_contacts: f.players_see_contacts !== false,
    players_see_faction_status: f.players_see_faction_status !== false,
  };
}

const STAND_FORM_PRESETS = ["Humanoid", "Non-Humanoid", "Phenomenon"];
const STAND_CONSCIOUSNESS_GRADES = ["A", "B", "C", "D", "E", "F"];
const STAND_IDENTITY_TYPE_KEYS = new Set(
  STAND_ARCHETYPE_ROWS.map((r) => r.key),
);

function normalizeStandFormsList(raw) {
  if (!Array.isArray(raw)) return [];
  const out = [];
  const seen = new Set();
  for (const x of raw) {
    const s = String(x || "").trim();
    if (!s || seen.has(s)) continue;
    seen.add(s);
    out.push(s);
  }
  return out;
}

function normalizeStandIdentityTypesLocal(raw) {
  if (!Array.isArray(raw)) return [];
  const out = [];
  const seen = new Set();
  for (const x of raw) {
    const s = String(x || "")
      .trim()
      .toUpperCase();
    if (!s || !STAND_IDENTITY_TYPE_KEYS.has(s) || seen.has(s)) continue;
    seen.add(s);
    out.push(s);
  }
  return out;
}

function normalizeStandConsciousnessLocal(raw) {
  const c = String(raw || "")
    .trim()
    .toUpperCase()
    .slice(0, 1);
  return STAND_CONSCIOUSNESS_GRADES.includes(c) ? c : "";
}

function clampStandingValue(n) {
  const v = Number(n);
  if (!Number.isFinite(v)) return 0;
  return Math.max(-3, Math.min(3, Math.trunc(v)));
}

function clampCrewStandingValue(n) {
  return clampStandingValue(n);
}

/** Legend labels for −3…+3 personal / crew standing. */
function standingTierLabel(v) {
  const n = clampStandingValue(v);
  if (n <= -3) return "War";
  if (n === -2) return "Hostile";
  if (n === -1) return "Interfering";
  if (n === 0) return "Neutral";
  if (n === 1) return "Helpful";
  if (n === 2) return "Friendly";
  return "Allied";
}

function formatStandingBadge(v) {
  const n = clampStandingValue(v);
  const signed = n > 0 ? `+${n}` : String(n);
  return `${signed} ${standingTierLabel(n)}`;
}

function normalizeStandingLocal(raw) {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const out = {};
  for (const [k, v] of Object.entries(raw)) {
    const sk = String(k).trim();
    if (!sk || !/^\d+$/.test(sk)) continue;
    out[sk] = clampStandingValue(v);
  }
  return out;
}

function normalizeCrewStandingLocal(raw) {
  return normalizeStandingLocal(raw);
}

function normalizePcStandingLocal(raw) {
  return normalizeStandingLocal(raw);
}

function readNpcSheetBool(npcId, key, fallback) {
  try {
    const id = npcId != null ? String(npcId) : "new";
    const raw = localStorage.getItem(`biz:npc-sheet:${id}:${key}`);
    if (raw === "true") return true;
    if (raw === "false") return false;
  } catch {
    /* ignore */
  }
  return fallback;
}

function writeNpcSheetBool(npcId, key, value) {
  try {
    const id = npcId != null ? String(npcId) : "new";
    localStorage.setItem(`biz:npc-sheet:${id}:${key}`, value ? "true" : "false");
  } catch {
    /* ignore */
  }
}

function newInventoryItemId() {
  if (typeof crypto !== "undefined" && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return `item-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

/** Resolve a freeform/manual contact to an openable NPC or PC sheet when possible. */
function resolveContactSheetLink(
  contact,
  { allNpcs = [], campaignPlayerCharacters = [] } = {},
) {
  if (!contact || typeof contact !== "object") return null;
  const npcIdRaw = contact.npc_id ?? contact.npcId;
  if (npcIdRaw != null && npcIdRaw !== "") {
    const id = Number(npcIdRaw);
    if (Number.isFinite(id)) {
      const entity = (allNpcs || []).find((n) => Number(n.id) === id) || {
        id,
        name: contact.name,
      };
      return { kind: "npc", id, entity };
    }
  }
  const pcIdRaw = contact.character_id ?? contact.characterId;
  if (pcIdRaw != null && pcIdRaw !== "") {
    const id = Number(pcIdRaw);
    if (Number.isFinite(id)) {
      const entity =
        (campaignPlayerCharacters || []).find((c) => Number(c.id) === id) || {
          id,
          name: contact.name,
        };
      return { kind: "pc", id, entity };
    }
  }
  const name = String(contact.name || "")
    .trim()
    .toLowerCase();
  if (!name) return null;
  const npcHits = (allNpcs || []).filter(
    (n) => String(n?.name || "").trim().toLowerCase() === name,
  );
  if (npcHits.length === 1) {
    return { kind: "npc", id: npcHits[0].id, entity: npcHits[0] };
  }
  const pcHits = (campaignPlayerCharacters || []).filter((ch) => {
    const labels = [ch.true_name, ch.name, ch.alias]
      .map((x) => String(x || "").trim().toLowerCase())
      .filter(Boolean);
    return labels.includes(name);
  });
  if (pcHits.length === 1) {
    return { kind: "pc", id: pcHits[0].id, entity: pcHits[0] };
  }
  return null;
}

function contactMatchesNpcId(contact, npcId) {
  const raw = contact?.npc_id ?? contact?.npcId;
  if (raw == null || raw === "") return false;
  return Number(raw) === Number(npcId);
}

function dispositionForNpcContact(list, npcId) {
  const row = (Array.isArray(list) ? list : []).find((c) =>
    contactMatchesNpcId(c, npcId),
  );
  return row?.disposition || "neutral";
}

/** Upsert disposition on a contact linked by npc_id; append if missing. */
function upsertNpcContactDisposition(list, npc, disposition) {
  const prev = Array.isArray(list) ? list : [];
  const npcId = Number(npc?.id);
  if (!Number.isFinite(npcId)) return prev;
  const idx = prev.findIndex((c) => contactMatchesNpcId(c, npcId));
  const label = npc.name || npc.stand_name || `NPC #${npcId}`;
  if (idx >= 0) {
    return prev.map((c, i) =>
      i === idx ? { ...c, disposition } : c,
    );
  }
  return [
    ...prev,
    {
      name: label,
      role: "Faction member",
      disposition,
      npc_id: npcId,
    },
  ];
}

