const arrowBtnStyle = {
  background: "none",
  border: "none",
  color: "#6b7280",
  cursor: "pointer",
  fontSize: "16px",
  padding: "2px 4px",
  lineHeight: 1,
};
const ProgressClock = ({
  size = 80,
  segments,
  filled,
  onClick,
  label,
  sublabel,
}) => {
  if (segments === 0) return null;
  const r = size / 2 - 4,
    cx = size / 2,
    cy = size / 2;
  const sa = 360 / segments;
  const svg = (
    <svg width={size} height={size} style={{ transform: "rotate(-90deg)" }}>
      {Array.from({ length: segments }, (_, i) => {
        const a1 = ((i * sa - 90) * Math.PI) / 180;
        const a2 = (((i + 1) * sa - 90) * Math.PI) / 180;
        const x1 = cx + r * Math.cos(a1),
          y1 = cy + r * Math.sin(a1);
        const x2 = cx + r * Math.cos(a2),
          y2 = cy + r * Math.sin(a2);
        return (
          <path
            key={i}
            d={`M ${cx} ${cy} L ${x1} ${y1} A ${r} ${r} 0 ${sa > 180 ? 1 : 0} 1 ${x2} ${y2} Z`}
            fill={i < filled ? clockWedgeFillColor(i, segments) : "transparent"}
            stroke="#4b5563"
            strokeWidth="1.5"
            style={{ cursor: onClick ? "pointer" : "default" }}
            onClick={
              onClick ? () => onClick(i < filled ? i : i + 1) : undefined
            }
          />
        );
      })}
      <circle
        cx={cx}
        cy={cy}
        r={r}
        fill="transparent"
        stroke="#6b7280"
        strokeWidth="2"
      />
      <text
        x={cx}
        y={cy}
        textAnchor="middle"
        dominantBaseline="middle"
        style={{
          fontSize: Math.max(8, size / 6),
          fill: "#fff",
          fontFamily: "monospace",
          fontWeight: "bold",
          transform: `rotate(90deg)`,
          transformOrigin: `${cx}px ${cy}px`,
        }}
      >
        {filled}/{segments}
      </text>
    </svg>
  );
  const clockContent = onClick ? (
    <div style={{ display: "flex", alignItems: "center", gap: "4px" }}>
      <button
        type="button"
        style={arrowBtnStyle}
        onClick={() => onClick(Math.max(0, filled - 1))}
        title="Decrease"
      >
        −
      </button>
      {svg}
      <button
        type="button"
        style={arrowBtnStyle}
        onClick={() => onClick(Math.min(segments, filled + 1))}
        title="Increase"
      >
        +
      </button>
    </div>
  ) : (
    svg
  );
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: "4px",
      }}
    >
      {clockContent}
      {label && (
        <div
          style={{
            fontSize: "11px",
            fontWeight: "bold",
            color: "#d1d5db",
            textAlign: "center",
            maxWidth: `${size}px`,
          }}
        >
          {label}
        </div>
      )}
      {sublabel && (
        <div
          style={{
            fontSize: "10px",
            color: "#6b7280",
            textAlign: "center",
            maxWidth: `${size}px`,
          }}
        >
          {sublabel}
        </div>
      )}
    </div>
  );
};

